5: export function useMobile() {
6:   const [isMobile, setIsMobile] = useState(false);
7:   const [isSidebarOpen, setIsSidebarOpen] = useState(false);
8: 
9:   const checkMobile = useCallback(() => {
10:     const mobile = window.innerWidth <= MOBILE_BREAKPOINT;
11:     setIsMobile(mobile);
12: 
13:     if (!mobile && isSidebarOpen) {
14:       setIsSidebarOpen(false);
15:       window.dispatchEvent(new CustomEvent("sidebar-close"));
16:     }
17:   }, [isSidebarOpen]);
18: 
19:   useEffect(() => {
20:     checkMobile();
21:     window.addEventListener("resize", checkMobile);
22: 
23:     const handleSidebarToggle = (event: Event) => {
24:       const customEvent = event as SidebarToggleEvent;
25:       setIsSidebarOpen(customEvent.detail.isOpen);
26:     };
27: 
28:     window.addEventListener(
29:       "sidebar-toggle",
30:       handleSidebarToggle as EventListener
31:     );
32: 
33:     return () => {
34:       window.removeEventListener("resize", checkMobile);
35:       window.removeEventListener(
36:         "sidebar-toggle",
37:         handleSidebarToggle as EventListener
38:       );
39:     };
40:   }, [checkMobile]);
41: 
42:   const closeSidebar = useCallback(() => {
43:     if (isMobile && isSidebarOpen) {
44:       setIsSidebarOpen(false);
45:       window.dispatchEvent(new CustomEvent("sidebar-close"));
46:     }
47:   }, [isMobile, isSidebarOpen]);
48: 
49:   return {
50:     isMobile,
51:     isSidebarOpen,
52:     closeSidebar,
53:   };
54: }

